CREATE TABLE mock_companies (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 company_name TEXT NOT NULL,
 risk_factor INTEGER NOT NULL CHECK(risk_factor BETWEEN 0 AND 100),
 decided_disbursement_cents INTEGER NOT NULL CHECK(decided_disbursement_cents >= 0 AND decided_disbursement_cents <= money_requested_cents),
 money_requested_cents INTEGER NOT NULL CHECK(money_requested_cents > 0),
 debtor TEXT NOT NULL,
 from_date TEXT NOT NULL,
 invoice_due TEXT NOT NULL,
 pool TEXT NOT NULL CHECK(pool = CASE WHEN risk_factor < 20 THEN 'Decline' WHEN risk_factor < 50 THEN 'Risky' WHEN risk_factor < 70 THEN 'Medium' ELSE 'Safe' END),
 source TEXT NOT NULL CHECK(source IN ('seed', 'application')),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX mock_companies_pool ON mock_companies(pool);
